// Vendor the pinned xterm distribution as strings for offline WKWebView/srcDoc.
import {createRequire} from 'node:module';
import {readFileSync,writeFileSync} from 'node:fs';
import {dirname,join} from 'node:path';
const require=createRequire(import.meta.url),root=dirname(require.resolve('@xterm/xterm/package.json'));
const js=readFileSync(join(root,'lib/xterm.js'),'utf8').replace(/\/\/# sourceMappingURL=.*$/m,'');
const css=readFileSync(join(root,'css/xterm.css'),'utf8');
writeFileSync(new URL('../src/ui/terminalAssets.ts',import.meta.url),`// Generated by mobile/scripts/bundle-terminal.mjs from @xterm/xterm 6.0.0 (MIT).\n// Do not edit; LICENSE is retained alongside this file.\nexport const xtermJs=${JSON.stringify(js)};\nexport const xtermCss=${JSON.stringify(css)};\n`);
writeFileSync(new URL('../src/ui/xterm-LICENSE.txt',import.meta.url),readFileSync(join(root,'LICENSE')));
